sys_script.script:
(function executeRule(current, previous /*null when async*/) {
    var relDocGr = new GlideRecord('cxs_relevant_doc');
    if (relDocGr.get(current.cxs_relevant_doc)) {
        var targetTable = relDocGr.getValue('source_doc_table');
        var targetSysId = relDocGr.getValue('source_doc');

        if (targetTable == 'interaction') {
            var kbSysId = current.getValue('relevant_doc');

            // Query interaction to get the Number
            var interactionNum = '';
            var intGr = new GlideRecord('interaction');
            if (intGr.get(targetSysId)) {
                interactionNum = intGr.getValue('number');
            }

            // Query kb_knowledge to get Number, Version, Short Description (Name)
            var kbNum = '';
            var kbVersion = '';
            var kbShortDesc = '';
            var kbGr = new GlideRecord('kb_knowledge');
            if (kbGr.get(kbSysId)) {
                kbNum = kbGr.getValue('number');
                kbVersion = kbGr.getValue('version') || '1.0';
                kbShortDesc = kbGr.getValue('short_description') || '';
            }

            // Overview Formatting: 'Interaction: [Number], KB: [Number], Version: [Version], Name: [Short Description]'
            var overviewStr = 'Interaction: ' + interactionNum + ', KB: ' + kbNum + ', Version: ' + kbVersion + ', Name: ' + kbShortDesc;

            // Insert new record into x_snc_pab_ee_tkit_m2m_interaction_to_knowledge_link
            var m2mGr = new GlideRecord('x_snc_pab_ee_tkit_m2m_interaction_to_knowledge_link');
            m2mGr.initialize();
            m2mGr.setValue('interaction', targetSysId);
            m2mGr.setValue('knowledge_article', kbSysId);
            m2mGr.setValue('overview', overviewStr);
            m2mGr.insert();
        }
    }
})(current, previous);
